import{_ as a,o,c as e,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const q=JSON.parse('{"title":"所罗门兄弟（Salomon Brothers）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/所罗门兄弟.md","filePath":"03_companies/所罗门兄弟.md"}'),d={name:"03_companies/所罗门兄弟.md"};function l(i,t,n,h,s,u){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="所罗门兄弟-salomon-brothers" tabindex="-1">所罗门兄弟（Salomon Brothers） <a class="header-anchor" href="#所罗门兄弟-salomon-brothers" aria-label="Permalink to &quot;所罗门兄弟（Salomon Brothers）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Salomon Brothers Inc.</td></tr><tr><td>行业</td><td>投资银行</td></tr><tr><td>总部</td><td>纽约</td></tr><tr><td>成立年份</td><td>1910年</td></tr><tr><td>伯克希尔投资</td><td>7亿美元可转换优先股</td></tr><tr><td>投资年份</td><td>1987年</td></tr><tr><td>投资成本</td><td>7亿美元</td></tr><tr><td>年固定股息</td><td>9%（约6,300万美元/年）</td></tr><tr><td>退出方式</td><td>1997年随旅行者集团收购退出</td></tr><tr><td>最终结果</td><td>优先股还本，略优于其替代的固定收益证券</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>所罗门兄弟是20世纪全球最具影响力的投资银行之一，核心业务包括：</p><ul><li><strong>政府债券交易</strong>：全球最大的政府债券交易商之一，在美国国债市场占据核心地位</li><li><strong>企业并购咨询</strong>：为大型企业提供并购、重组等投资银行服务</li><li><strong>固定收益产品</strong>：债券承销、利率衍生品等</li><li><strong>机构销售</strong>：向全球机构投资者提供证券销售与交易服务</li></ul><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="历史渊源" tabindex="-1">历史渊源 <a class="header-anchor" href="#历史渊源" aria-label="Permalink to &quot;历史渊源&quot;">​</a></h3><ul><li><strong>1976年</strong>：<a href="/03_companies/GEICO">GEICO</a>濒临破产时，所罗门兄弟帮助承销了其融资，<a href="/search?q=约翰·古弗兰德">约翰·古弗兰德</a>（John Gutfreund）鼎力相助。巴菲特因此对古弗兰德心存感激，这也成为巴菲特1987年投资所罗门兄弟的重要原因之一。</li></ul><h3 id="投资决策-1987年" tabindex="-1">投资决策（1987年） <a class="header-anchor" href="#投资决策-1987年" aria-label="Permalink to &quot;投资决策（1987年）&quot;">​</a></h3><p>1987年9月，巴菲特以7亿美元购入所罗门兄弟9%可转换优先股。巴菲特在1987年股东信中解释了投资逻辑：</p><blockquote><p>&quot;我们1987年我们拿了七亿<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>9%可转优先股，我们没有对投行未来我们没看法，我们喜欢约翰·古弗兰德董事长，我们认识他1976年<a href="/03_companies/GEICO">GEICO</a>快破产，他帮了大忙，他人品我们信得过，我们觉得这个生意我们愿意合伙，所以我们买了，年底我们价值九十八 percent 面值，亏一千四百万，我们觉得，他做的好，未来肯定会好。&quot;</p></blockquote><h3 id="完整时间线" tabindex="-1">完整时间线 <a class="header-anchor" href="#完整时间线" aria-label="Permalink to &quot;完整时间线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>事件</th><th>关键数据/要点</th></tr></thead><tbody><tr><td><strong>1987年9月</strong></td><td>巴菲特买入所罗门兄弟优先股</td><td>7亿美元，9%年息，可转换为普通股</td></tr><tr><td><strong>1987年底</strong></td><td>估值略有折价</td><td>面值98%，浮亏约1,400万美元</td></tr><tr><td><strong>1988年</strong></td><td>继续持有，转换权价值未体现</td><td>&quot;年底市值适度高于成本&quot;</td></tr><tr><td><strong>1989年</strong></td><td>继续持有，深化合作</td><td>巴菲特与古弗兰德合作更愉快，但称&quot;对投行未来还是没法预测&quot;</td></tr><tr><td><strong>1990年</strong></td><td>所罗门正常运营，优先股持续分红</td><td>年息6,300万美元稳定到账</td></tr><tr><td><strong>1991年5月</strong></td><td><strong>国债投标丑闻爆发</strong></td><td>员工莫舍·梅赫尔越过监管上限竞标美国国债，古弗兰德知情未报</td></tr><tr><td><strong>1991年8月</strong></td><td>财政部暂停所罗门国债交易资格</td><td>公司面临存亡危机，股价暴跌</td></tr><tr><td><strong>1991年8月</strong></td><td><strong>巴菲特出任临时董事长</strong></td><td>应古弗兰德请求介入，试图挽救公司</td></tr><tr><td><strong>1991年9月</strong></td><td>丑闻余波</td><td>SEC、联邦检察官、联储等多机构介入调查</td></tr><tr><td><strong>1991年底</strong></td><td>巴菲特卸任临时董事长</td><td>任临时董事长约10周（8月~9月）</td></tr><tr><td><strong>1992年</strong></td><td>危机彻底平息</td><td>&quot;已经理顺了，我们持股不变，股价还涨了一点&quot;</td></tr><tr><td><strong>1995年</strong></td><td>所罗门与旅行者集团合并谈判启动</td><td>鲍勃·德纳姆（Bob Denham）任CEO</td></tr><tr><td><strong>1997年</strong></td><td><strong>旅行者集团以90亿美元收购所罗门兄弟</strong></td><td>伯克希尔优先股被合并为旅行者股票</td></tr><tr><td><strong>1997年后</strong></td><td>伯克希尔逐步减持旅行者股份</td><td>最终获利退出</td></tr><tr><td><strong>1999年</strong></td><td>清仓</td><td>伯克希尔彻底退出</td></tr></tbody></table><h3 id="_1991年所罗门危机详细过程" tabindex="-1">1991年所罗门危机详细过程 <a class="header-anchor" href="#_1991年所罗门危机详细过程" aria-label="Permalink to &quot;1991年所罗门危机详细过程&quot;">​</a></h3><p>1991年5月，所罗门兄弟国债交易员<strong>莫舍·梅赫尔</strong>（Moshe Meryhew / 实际为 Paul Mooney / 注：1991年信中称&quot;梅尔文·梅尔&quot;，真实身份为 Paul Mooney，摩西·梅尔为化名）在竞标美国国债时故意越过财政部规定的单一投标者上限（竞标总额上限），以规避对投标人的限制性规定。调查显示，他曾多次以他人或关联公司的名义投标，累计超过规定上限。</p><p>问题曝光路径：</p><ol><li>纽约联邦储备银行在日常市场监控中发现异常</li><li>财政部开始调查</li><li>公司内部审查发现问题严重性</li><li>1991年8月，<a href="/search?q=约翰·古弗兰德">约翰·古弗兰德</a>被迫承认自己曾被告知相关情况但未向监管机构报告</li></ol><p><strong>危机高峰时刻</strong>：</p><ul><li>1991年8月，<strong>美国财政部宣布暂停所罗门兄弟参与国债拍卖的资格</strong></li><li>所罗门股价单日暴跌，引发客户和交易对手恐慌</li><li>公司面临被强制清算的边缘——拥有8,000名员工的机构可能就此倒闭</li><li><strong>古弗兰德请求巴菲特出任临时董事长</strong></li><li>巴菲特在1991年8月临危受命，出任临时董事长</li><li>巴菲特后来在2019年股东信中回顾：&quot;不愿立即面对坏消息，将<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>的问题从本可以轻松解决的问题变成了几乎导致一家拥有8,000名员工的公司demise的问题。&quot;</li></ul><p><strong>危机化解的关键人物</strong>（巴菲特在1992年股东信中特别致谢）：</p><ul><li><strong>德里克·莫恩</strong>（Derek Mooney）：危机后任CEO，与鲍勃·德纳姆共同主导了拯救与重组</li><li><strong>鲍勃·德纳姆</strong>（Bob Denham）：1995年起任CEO，主导了旅行者集团合并谈判</li><li><strong>唐·霍华德</strong>（Don Howard）：危机期间留守高管</li><li><strong>约翰·麦克法兰</strong>（John MacFarlane）：危机期间留守高管</li><li><strong>罗恩·奥尔森</strong>（Ron Olson）：芒格-托尔斯-奥尔森律师事务所，为危机解决提供关键法律支持</li></ul><p>巴菲特1992年写道：&quot;毫不夸张地说，如果没有<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>高管德里克·莫恩、鲍勃·德纳姆、唐·霍华德和约翰·麦克法兰的共同努力，公司很可能无法存活。&quot;</p><h3 id="危机后续与合并" tabindex="-1">危机后续与合并 <a class="header-anchor" href="#危机后续与合并" aria-label="Permalink to &quot;危机后续与合并&quot;">​</a></h3><ul><li>1991年底巴菲特卸任临时董事长后，德里克·莫恩接任领导公司重组</li><li>1995年，鲍勃·德纳姆出任CEO，公司逐步恢复</li><li>1997年，所罗门兄弟与<strong>旅行者集团</strong>（Travelers Group）合并（后于1998年与花旗集团合并）</li><li>巴菲特1997年评价：&quot;<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>所有股东——包括我，非常个人化——都欠德里克·莫恩和鲍勃·德纳姆巨大的债务，因为首先，在1991年丑闻后拯救<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>免于灭绝方面发挥了关键作用，其次，将公司的活力恢复到使其成为旅行者有吸引力的收购对象的水平。&quot;</li></ul><h3 id="巴菲特出任临时董事长的意外与反思" tabindex="-1">巴菲特出任临时董事长的意外与反思 <a class="header-anchor" href="#巴菲特出任临时董事长的意外与反思" aria-label="Permalink to &quot;巴菲特出任临时董事长的意外与反思&quot;">​</a></h3><p>巴菲特在1992年股东信中坦言，这次经历完全出乎意料：</p><blockquote><p>&quot;我们的其他两笔优先股令人失望，不过<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>的优先股略优于它所替代的固定收益证券。然而，查理和我在这个持仓上花费的管理时间远超过其对<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>的经济意义。我当然从未梦想过我会因为早期购买固定收益证券而在60岁时接受一份新工作——<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>临时董事长。&quot;</p></blockquote><blockquote><p>&quot;1987年我们购买<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>优先股后不久，我写道，我&#39;对投资银行业的方向或未来盈利能力没有特别的洞察力。&#39;即使是最仁慈的评论家也会得出结论：此后我证明了这一点。&quot;</p></blockquote><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><ul><li><strong>国债市场地位</strong>：美国国债市场的核心做市商，流动性无与伦比</li><li><strong>债券研究能力</strong>：拥有业内最顶尖的固定收益研究团队</li><li><strong>并购顾问传统</strong>：所罗门在大型并购交易中的品牌声誉</li><li><strong>管理层危机处理</strong>：1991年后德里克·莫恩和鲍勃·德纳姆证明的重建能力</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><h3 id="_1987年-投资决策" tabindex="-1">1987年（投资决策） <a class="header-anchor" href="#_1987年-投资决策" aria-label="Permalink to &quot;1987年（投资决策）&quot;">​</a></h3><blockquote><p>&quot;我们1987年我们拿了七亿<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>9%可转优先股，我们没有对投行未来我们没看法，我们喜欢约翰·古弗兰德董事长，我们认识他1976年<a href="/03_companies/GEICO">GEICO</a>快破产，他帮了大忙，他人品我们信得过，我们觉得这个生意我们愿意合伙，所以我们买了。&quot;</p></blockquote><blockquote><p>&quot;年底这项投资价值约98%面值，亏一千四百万，我们觉得，他做的好，未来肯定会好。&quot;</p></blockquote><h3 id="_1988年-持有中" tabindex="-1">1988年（持有中） <a class="header-anchor" href="#_1988年-持有中" aria-label="Permalink to &quot;1988年（持有中）&quot;">​</a></h3><blockquote><p>&quot;<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>九percent可转优先股我们持有七亿，我们年底市值适度高于成本，我们过去一年和John Gutfreund合作，更加欣赏他，我们对投行未来还是没法预测，这个行业不容易预测未来盈利能力，我们相信我们转换权未来肯定有价值，但是大部分价值还是固定收益特性，不是股权特性。&quot;</p></blockquote><h3 id="_1989年-持续合作" tabindex="-1">1989年（持续合作） <a class="header-anchor" href="#_1989年-持续合作" aria-label="Permalink to &quot;1989年（持续合作）&quot;">​</a></h3><blockquote><p>&quot;我们发行了九亿零两百六十万本金零息可转换次级债，纽交所上市，<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>承销做得很棒，给我们很好建议，执行完美。&quot;</p></blockquote><h3 id="_1991年-危机爆发" tabindex="-1">1991年（危机爆发） <a class="header-anchor" href="#_1991年-危机爆发" aria-label="Permalink to &quot;1991年（危机爆发）&quot;">​</a></h3><blockquote><p>&quot;<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>事件，我去当了临时董事长，已经理顺了，我们持股不变，股价还涨了一点，我们觉得长期没问题。&quot;</p></blockquote><h3 id="_1992年-危机善后与致谢" tabindex="-1">1992年（危机善后与致谢） <a class="header-anchor" href="#_1992年-危机善后与致谢" aria-label="Permalink to &quot;1992年（危机善后与致谢）&quot;">​</a></h3><blockquote><p>&quot;去年6月，在担任<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>公司临时董事长十个月后，我卸任了。从<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>1991-92年的业绩可以看出，我不在期间公司并没有想念我。但反过来说并不成立：我想念<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>，很高兴能全职回来。世界上没有比经营<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>更有趣的工作了，我庆幸自己能在现在这个位置。&quot;</p></blockquote><blockquote><p>&quot;毫不夸张地说，如果没有<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>高管德里克·莫恩、鲍勃·德纳姆、唐·霍华德和约翰·麦克法兰的共同努力，公司很可能无法存活。在工作中，这些人不知疲倦、高效、支持他人且无私，我将永远感激他们。&quot;</p></blockquote><blockquote><p>&quot;在《财富》杂志去年9月进行的美国最受尊敬公司年度调查中，<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>在改善声誉程度方面在311家公司中排名第二。此外，<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>公司去年报告了创纪录的税前收益——比此前最高纪录高出34%。&quot;</p></blockquote><h3 id="_1995年-合作深化" tabindex="-1">1995年（合作深化） <a class="header-anchor" href="#_1995年-合作深化" aria-label="Permalink to &quot;1995年（合作深化）&quot;">​</a></h3><blockquote><p>&quot;幸运的是，理查德也是<a href="/03_companies/飞安国际">飞安国际</a>的长期股东……因此，7月份，理查德写信给<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>公司首席执行官鲍勃·登纳姆，建议他探索合并的可能性。&quot;</p></blockquote><h3 id="_1996年-危机后反思" tabindex="-1">1996年（危机后反思） <a class="header-anchor" href="#_1996年-危机后反思" aria-label="Permalink to &quot;1996年（危机后反思）&quot;">​</a></h3><blockquote><p>&quot;我当然从未梦想过我会因为早期购买固定收益证券而在60岁时接受一份新工作——<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>临时董事长。&quot;</p></blockquote><blockquote><p>&quot;1987年我们购买<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>优先股后不久，我写道，我&#39;对投资银行业的方向或未来盈利能力没有特别的洞察力。&#39;即使是最仁慈的评论家也会得出结论：此后我证明了这一点。&quot;</p></blockquote><blockquote><p>&quot;到目前为止，我们的转换为<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>普通股的权利尚未被证明有价值。此外，自我承诺购买优先股以来，道琼斯工业平均指数已经翻了一番，券商行业也表现得同样出色。这意味着我因为在转换期权中看到价值而选择<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>的决定必须被评为非常糟糕。尽管如此，在某些困难条件下，优先股作为固定收益证券继续发挥了应有的作用，9%的股息目前相当有吸引力。&quot;</p></blockquote><blockquote><p>&quot;去年我们向<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>开出了四张支票，每次我们都对自己支付的工作非常满意……特里·菲茨杰拉德领导了这项工作，我们感谢他所做的工作。&quot;</p></blockquote><blockquote><p>&quot;如果我们年底决定发行<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>票据时——这些票据可以交换我们持有的部分<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>股票——我们再次求助于特里。在这种情况下，<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>再次做得非常出色，以4.471亿美元出售了5亿美元本金的五年期票据。&quot;</p></blockquote><blockquote><p>&quot;就1996年<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>的交易而言，我们完全物有所值。&quot;</p></blockquote><h3 id="_1997年-合并退出" tabindex="-1">1997年（合并退出） <a class="header-anchor" href="#_1997年-合并退出" aria-label="Permalink to &quot;1997年（合并退出）&quot;">​</a></h3><blockquote><p>&quot;<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>最近与旅行者集团合并。<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>的所有股东——包括我，非常个人化——都欠德里克·莫恩和鲍勃·德纳姆巨大的债务，因为首先，在1991年丑闻后拯救<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>免于灭绝方面发挥了关键作用，其次，将公司的活力恢复到使其成为旅行者有吸引力的收购对象的水平。&quot;</p></blockquote><blockquote><p>&quot;<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>从其<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>投资的最终结果还需要一段时间才能计算出来，但可以肯定地说，它们将比我两年前预期的要好得多。&quot;</p></blockquote><blockquote><p>&quot;回顾过去，我认为我的<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>经历既迷人又有教育意义，尽管在1991-92年的一段时间里，我感觉像戏剧评论家写道：&#39;我会享受这出戏，只是我有一个不幸的座位。它面对舞台。&#39;&quot;</p></blockquote><h3 id="_2019年-长期反思" tabindex="-1">2019年（长期反思） <a class="header-anchor" href="#_2019年-长期反思" aria-label="Permalink to &quot;2019年（长期反思）&quot;">​</a></h3><blockquote><p>&quot;不愿立即面对坏消息，将<a href="/03_companies/所罗门兄弟">所罗门兄弟</a>的问题从本可以轻松解决的问题变成了几乎导致一家拥有8,000名员工的公司demise的问题。&quot;</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><h3 id="优先股条款明细" tabindex="-1">优先股条款明细 <a class="header-anchor" href="#优先股条款明细" aria-label="Permalink to &quot;优先股条款明细&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条款</th><th>内容</th></tr></thead><tbody><tr><td>投资金额</td><td>7亿美元</td></tr><tr><td>年息率</td><td>9%（固定）</td></tr><tr><td>年股息收入</td><td>约6,300万美元</td></tr><tr><td>转换权</td><td>可转换为普通股（价值从未充分体现）</td></tr><tr><td>购买时间</td><td>1987年9月</td></tr><tr><td>退出方式</td><td>1997年随旅行者集团收购转换为旅行者股票</td></tr></tbody></table><h3 id="各年度估值情况" tabindex="-1">各年度估值情况 <a class="header-anchor" href="#各年度估值情况" aria-label="Permalink to &quot;各年度估值情况&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>估值说明</th></tr></thead><tbody><tr><td>1987年底</td><td>面值98%，浮亏约1,400万美元</td></tr><tr><td>1988年底</td><td>市值适度高于成本</td></tr><tr><td>1989-1990年</td><td>优先股分红正常，转换权价值未体现</td></tr><tr><td>1991年</td><td>危机期间股价暴跌，但优先股仍获偿付</td></tr><tr><td>1992年</td><td>危机平息后股价回升至略高于成本</td></tr><tr><td>1993-1994年</td><td>优先股持续分红，价值平稳</td></tr><tr><td>1995年</td><td>鲍勃·德纳姆任CEO，公司复苏</td></tr><tr><td>1997年</td><td>与旅行者集团合并，优先股转为旅行者股票</td></tr></tbody></table><h3 id="投资最终结果评估" tabindex="-1">投资最终结果评估 <a class="header-anchor" href="#投资最终结果评估" aria-label="Permalink to &quot;投资最终结果评估&quot;">​</a></h3><p>巴菲特对这笔投资的最终评价是<strong>混合的</strong>：</p><ul><li><strong>作为固定收益投资</strong>：9%的年息稳定可靠，最终还本，优于当时替代的固定收益证券</li><li><strong>作为股权投资</strong>：转换权从未充分体现价值——1987年后道指翻番，投行业表现同步，但所罗门普通股从未给伯克希尔带来超额回报</li><li><strong>经济账</strong>：优先股最终还本，附加多年股息，整体回报尚可，但远不如<a href="/03_companies/吉列">吉列</a>等成功转股的优先股</li><li><strong>时间成本</strong>：巴菲特为此花费了远超经济意义的个人时间和精力</li></ul><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>与伯克希尔的关系</th></tr></thead><tbody><tr><td><a href="/search?q=约翰·古弗兰德">约翰·古弗兰德</a>（John Gutfreund）</td><td>董事长兼CEO（1987-1991）</td><td>1976年帮<a href="/03_companies/GEICO">GEICO</a>融资；1987年邀请巴菲特投资；国债丑闻后请求巴菲特出任临时董事长</td></tr><tr><td>德里克·莫恩（Derek Mooney）</td><td>危机后CEO（1991-1995）</td><td>危机期间核心救星；1997年旅行者合并后离职</td></tr><tr><td>鲍勃·德纳姆（Bob Denham）</td><td>CEO（1995-1997）</td><td>主导所罗门复苏；主导旅行者合并谈判；1996年帮助伯克希尔完成B类股增发等多项交易</td></tr><tr><td>莫舍·梅赫尔（Paul Mooney/梅尔文·梅尔）</td><td>国债交易员</td><td>越权投标引发1991年国债危机（员工，非高管）</td></tr><tr><td>罗恩·奥尔森（Ron Olson）</td><td>芒格-托尔斯-奥尔森律师事务所律师</td><td>为危机解决提供关键法律支持</td></tr></tbody></table><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1987年（首次投资） → 1988年 → 1989年 → 1991年（危机） → 1992年（危机善后） → 1995年 → 1996年（深度合作与反思） → 1997年（合并退出） → 2019年（长期反思） → 2022年</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/GEICO">GEICO</a> - 1976年所罗门帮助其融资的保险公司，所罗门-巴菲特关系的起点</li><li><a href="/search?q=约翰·古弗兰德">约翰·古弗兰德</a> - 所罗门兄弟前董事长，1987年投资的主要决策人</li><li><a href="/search?q=首都城市ABC">首都城市ABC</a> - 同为1980年代大额投资，同样涉及优先股结构</li><li><a href="/03_companies/吉列">吉列</a> - 同期可转换优先股投资（最终成功转股并大赚，与所罗门形成对比）</li><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> - 投资者本身</li></ul><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/1987年/翻译">1987年</a> - 首次披露投资决策</li><li><a href="./../01_letters/1988年/翻译">1988年</a> - 优先股持有情况</li><li><a href="./../01_letters/1989年/翻译">1989年</a> - 承销合作</li><li><a href="./../01_letters/1991年/翻译">1991年</a> - 危机爆发与临时董事长</li><li><a href="./../01_letters/1992年/翻译">1992年</a> - 危机善后与致谢</li><li><a href="./../01_letters/1995年/翻译">1995年</a> - 飞安国际收购中介</li><li><a href="./../01_letters/1996年/翻译">1996年</a> - 多项深度合作与反思</li><li><a href="./../01_letters/1997年/翻译">1997年</a> - 旅行者集团合并</li><li><a href="./../01_letters/2019年/翻译">2019年</a> - 长期教训回顾</li><li><a href="./../01_letters/2022年/翻译">2022年</a> - 长期教训回顾</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/03_companies/所罗门兄弟">1987年：完整翻译|/01_letters/1987年/翻译</a></li><li><a href="/03_companies/所罗门兄弟">1991年：完整翻译|/01_letters/1991年/翻译</a></li><li><a href="/03_companies/所罗门兄弟">1992年：完整翻译|/01_letters/1992年/翻译</a></li><li><a href="/03_companies/所罗门兄弟">1997年：完整翻译|/01_letters/1997年/翻译</a></li></ul><hr><p><em>最后更新：2026-04-16</em></p>',81)])])}const p=a(d,[["render",l]]);export{q as __pageData,p as default};
